import os
import boto3
from urllib.parse import urlparse
from queue import Queue
from typing import Dict, Any

s3_client = boto3.client("s3")

def _check_file_exists(cache_dir: str, file_path: str) -> bool:
    local_filename = os.path.basename(file_path.lstrip("/"))
    local_file_path = os.path.join(cache_dir, local_filename)
    if os.path.exists(local_file_path):
        return True
    return False

def _download_data_target(input_dir: Dict[str, Any], cache_dir: str, queue_in: Queue, queue_out: Queue) -> None:
    while True:
        try:
            index, file_paths = queue_in.get_nowait()
            for file_path in file_paths:
                obj = urlparse(file_path)
                if obj.scheme == "s3":
                    if _check_file_exists(cache_dir, file_path):
                        continue
                    try:
                        s3_client.head_object(Bucket=obj.netloc, Key=obj.path.lstrip("/"))
                        local_filename = os.path.basename(obj.path.lstrip("/"))
                        s3_client.download_file(Bucket=obj.netloc, Key=obj.path.lstrip("/"), Filename=os.path.join(cache_dir, local_filename))
                    except botocore.exceptions.ClientError as e:
                        if "Not Found" in str(e):
                            continue
                        else:
                            raise
                    queue_out.put(index)
        except Queue.Empty:
            continue
