from typing import List, Iterable, TypeVar
import itertools

T = TypeVar('T')

class Node:
    def __init__(self, modules: List[Module]):
        self.modules = modules

class Module:
    def __init__(self, name: str, module_params: List[ModuleParam]):
        self.name = name
        self.module_params = module_params

class ModuleParam:
    def __init__(self, key: str, value: str):
        self.key = key
        self.value = value

def extract_values(node: Node, key: str) -> Iterable[str]:
    for module in node.modules:
        for param in module.module_params:
            if param.key == key:
                yield param.value

def extract_values_from_nodes(nodes: List[Node], key: str) -> List[str]:
    values_from_nodes = list(map(extract_values, nodes, itertools.repeat(key)))
    flattened_values = list(itertools.chain.from_iterable(values_from_nodes))
    unique_values = list(set(flattened_values))
    return unique_values
